package com.forcemind.chatgpt.profiles;

import android.app.AlertDialog;
import android.content.Context;
import android.graphics.Color;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** A transient dialogue list. Opening it never detaches or recreates a webpage. */
final class TabOverview extends FrameLayout {
    interface Host {
        WorkspaceState state();void activate(String account,String tab);void add(String account);void close(String account,String tab);
        void restore(String account,String tab);void pin(String account,String tab);void rename(String account,String tab,String title);void move(String account,String tab,int direction);void done();
    }
    private final Host host;private final TextView summary;private final EditText search;private final LinearLayout filters,panel;private final ListView list;private final Rows adapter=new Rows();private String filter;
    private final List<Entry> visible=new ArrayList<>();
    private record Entry(WorkspaceState.Account account,WorkspaceState.Tab tab){}
    TabOverview(Context context,Host host){
        super(context);this.host=host;filter=host.state().activeAccount;setContentDescription("标签页面板");setBackgroundColor(0x44000000);setClickable(true);setFocusableInTouchMode(true);setOnClickListener(v->host.done());
        panel=new LinearLayout(context);panel.setOrientation(LinearLayout.VERTICAL);panel.setBackground(round(Color.WHITE,0,20));panel.setClipToOutline(true);panel.setClickable(true);addView(panel);
        LinearLayout top=new LinearLayout(context);top.setGravity(Gravity.TOP);top.setPadding(dp(20),dp(20),dp(12),dp(14));panel.addView(top,new LinearLayout.LayoutParams(-1,-2));LinearLayout titles=new LinearLayout(context);titles.setOrientation(LinearLayout.VERTICAL);TextView title=text("标签页",19);title.setTypeface(null,android.graphics.Typeface.BOLD);titles.addView(title);summary=text("",13);StudioTypography.meta(summary);titles.addView(summary);top.addView(titles,new LinearLayout.LayoutParams(0,-2,1));Button done=button("完成");done.setOnClickListener(v->host.done());top.addView(done,new LinearLayout.LayoutParams(-2,-2));
        LinearLayout query=new LinearLayout(context);query.setGravity(Gravity.CENTER_VERTICAL);query.setPadding(dp(10),0,dp(8),0);query.setBackground(round(Color.WHITE,0xffd4d4d4,12));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,StudioTypography.lineBox(context,15,1,16,48));qp.setMargins(dp(20),0,dp(20),dp(12));panel.addView(query,qp);ImageView magnifier=new ImageView(context);magnifier.setImageDrawable(new StudioIcon("search"));query.addView(magnifier,new LinearLayout.LayoutParams(dp(18),dp(18)));
        search=new EditText(context);StudioTypography.text(search,15);search.setSingleLine(true);search.setTextColor(StudioTypography.INK);search.setHintTextColor(StudioTypography.MUTED);search.setPadding(dp(8),dp(8),dp(8),dp(8));search.setBackgroundColor(Color.TRANSPARENT);search.setHint("搜索标签页或账号");search.setContentDescription("搜索标签页或账号");search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(300)});query.addView(search,new LinearLayout.LayoutParams(0,-1,1));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){refreshRows();}public void afterTextChanged(Editable e){}});
        filters=new LinearLayout(context);filters.setPadding(dp(20),0,dp(20),dp(12));panel.addView(filters,new LinearLayout.LayoutParams(-1,-2));
        FrameLayout listArea=new FrameLayout(context);panel.addView(listArea,new LinearLayout.LayoutParams(-1,0,1));list=new ListView(context);list.setDivider(null);list.setPadding(dp(20),0,dp(20),dp(12));list.setClipToPadding(false);list.setAdapter(adapter);listArea.addView(list,new FrameLayout.LayoutParams(-1,-1));TextView empty=text("没有找到标签页，换一个名称或账号试试。",14);empty.setPadding(dp(20),dp(24),dp(20),dp(24));empty.setGravity(Gravity.CENTER);listArea.addView(empty,new FrameLayout.LayoutParams(-1,-1));list.setEmptyView(empty);
        LinearLayout footer=new LinearLayout(context);footer.setOrientation(LinearLayout.VERTICAL);footer.setPadding(dp(20),dp(12),dp(20),dp(16));panel.addView(footer,new LinearLayout.LayoutParams(-1,-2));Button recent=button("最近关闭");recent.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);recent.setOnClickListener(v->recent());footer.addView(recent,new LinearLayout.LayoutParams(-1,-2));Button add=button("＋ 新建标签页");add.setContentDescription("新建标签页");add.setTextColor(Color.WHITE);add.setBackground(round(StudioTypography.INK,0,12));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,-2);ap.topMargin=dp(8);footer.addView(add,ap);add.setOnClickListener(v->host.add(filter.equals("all")?host.state().activeAccount:filter));
        requestFocus();refresh();
    }
    @Override protected void onMeasure(int width,int height){int w=MeasureSpec.getSize(width),h=MeasureSpec.getSize(height);boolean tablet=getResources().getConfiguration().screenWidthDp>=600;int pw=tablet?Math.max(0,Math.min(dp(420),w-dp(24))):-1,ph=tablet?Math.max(0,h-dp(24)):Math.round(h*.94f),gravity=tablet?Gravity.END|Gravity.TOP:Gravity.BOTTOM;FrameLayout.LayoutParams old=(FrameLayout.LayoutParams)panel.getLayoutParams();if(old.width!=pw||old.height!=ph||old.gravity!=gravity){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(pw,ph,gravity);if(tablet)p.setMargins(dp(12),dp(12),dp(12),dp(12));panel.setLayoutParams(p);}super.onMeasure(width,height);}
    String query(){return search.getText().toString();}String filter(){return filter;}int position(){return list.getFirstVisiblePosition();}
    void restoreUI(String filter,String query,int position){if(filter.equals("all")||host.state().accounts.stream().anyMatch(a->a.id.equals(filter)))this.filter=filter;search.setText(query);refresh();list.setSelection(Math.max(0,position));}
    void refresh(){WorkspaceState state=host.state();summary.setText(state.current().name+" · "+state.current().tabs.size()+" 个");filters.removeAllViews();chip(state.activeAccount,"当前账号");chip("all","全部账号");refreshRows();}
    private void chip(String id,String label){Button chip=button(label);chip.setTextColor(id.equals(filter)?Color.WHITE:StudioTypography.INK);chip.setBackground(round(id.equals(filter)?StudioTypography.INK:0xfff4f4f4,0,9));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.rightMargin=dp(8);filters.addView(chip,p);chip.setOnClickListener(v->{filter=id;refresh();});}
    private void refreshRows(){if(list==null)return;String q=query().trim().toLowerCase(Locale.ROOT);visible.clear();for(WorkspaceState.Account account:host.state().accounts)for(WorkspaceState.Tab tab:account.tabs)if((filter.equals("all")||filter.equals(account.id))&&(tab.title+" "+account.name).toLowerCase(Locale.ROOT).contains(q))visible.add(new Entry(account,tab));visible.sort((a,b)->Boolean.compare(b.tab.pinned,a.tab.pinned));adapter.notifyDataSetChanged();}
    private void menu(Entry entry){StudioSheet sheet=new StudioSheet(getContext(),"标签管理",entry.tab.title);sheet.row(entry.tab.pinned?"取消固定":"固定标签页","","pin",()->{host.pin(entry.account.id,entry.tab.id);sheet.dismiss();refresh();});sheet.row("重命名","","edit",()->{sheet.dismiss();rename(entry);});sheet.row("向前移动","","",()->{host.move(entry.account.id,entry.tab.id,-1);sheet.dismiss();refresh();});sheet.row("向后移动","","",()->{host.move(entry.account.id,entry.tab.id,1);sheet.dismiss();refresh();});sheet.row("关闭标签页","","close",()->{sheet.dismiss();host.close(entry.account.id,entry.tab.id);refresh();});sheet.show();}
    private void rename(Entry entry){EditText input=new EditText(getContext());StudioTypography.text(input,15);input.setText(entry.tab.title);input.setSingleLine(true);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});input.setContentDescription("标签名称");new AlertDialog.Builder(getContext()).setTitle("重命名标签页").setView(input).setNegativeButton("取消",null).setPositiveButton("保存",(d,n)->{String value=input.getText().toString().trim();if(!value.isEmpty())host.rename(entry.account.id,entry.tab.id,value);refresh();}).show();}
    private void recent(){StudioSheet sheet=new StudioSheet(getContext(),"最近关闭","关闭标签页不会删除 ChatGPT 中的历史会话。");List<Entry> closed=new ArrayList<>();for(WorkspaceState.Account account:host.state().accounts)if(filter.equals("all")||filter.equals(account.id))for(int i=account.closedTabs.size()-1;i>=0;i--)closed.add(new Entry(account,account.closedTabs.get(i)));if(closed.isEmpty())sheet.body.addView(sheet.text("还没有最近关闭的标签页",15));for(Entry entry:closed)sheet.row(entry.tab.title,entry.account.name,"history",()->{sheet.dismiss();host.restore(entry.account.id,entry.tab.id);});sheet.show();}
    private final class Rows extends BaseAdapter {
        public int getCount(){return visible.size();}public Object getItem(int n){return visible.get(n);}public long getItemId(int n){return n;}
        public View getView(int n,View recycled,ViewGroup parent){
            Entry entry=visible.get(n);LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(13),dp(8),dp(13));boolean active=entry.account.id.equals(host.state().activeAccount)&&entry.tab.id.equals(entry.account.activeTab);row.setBackground(round(active?0xfffafafa:Color.WHITE,0,14));row.setForeground(round(Color.TRANSPARENT,active?StudioTypography.INK:0xffdedede,14));row.setContentDescription("标签页："+entry.tab.title+"，账号："+entry.account.name);row.setClickable(true);row.setFocusable(true);row.setOnClickListener(v->host.activate(entry.account.id,entry.tab.id));row.setOnLongClickListener(v->{menu(entry);return true;});
            ImageView symbol=new ImageView(getContext());symbol.setImageDrawable(new StudioIcon(active?"check":"chat"));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(20),dp(20));sp.rightMargin=dp(10);row.addView(symbol,sp);
            LinearLayout copy=new LinearLayout(getContext());copy.setOrientation(LinearLayout.VERTICAL);TextView title=text(entry.tab.title,15);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);copy.addView(title);LinearLayout meta=new LinearLayout(getContext());meta.setGravity(Gravity.CENTER_VERTICAL);View dot=new View(getContext());dot.setBackground(round(Color.parseColor(entry.account.color),0,4));LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(dp(6),dp(6));dp.rightMargin=dp(6);meta.addView(dot,dp);TextView account=text(entry.account.name+(entry.tab.pinned?" · 已固定":""),13);StudioTypography.meta(account);account.setMaxLines(2);meta.addView(account,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,-2);mp.topMargin=dp(5);copy.addView(meta,mp);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));
            LinearLayout actions=new LinearLayout(getContext());actions.setOrientation(LinearLayout.VERTICAL);ImageButton more=icon("more","管理标签页："+entry.tab.title);more.setOnClickListener(v->menu(entry));actions.addView(more,new LinearLayout.LayoutParams(dp(44),dp(44)));ImageButton close=icon("close","关闭标签页："+entry.tab.title);close.setOnClickListener(v->{host.close(entry.account.id,entry.tab.id);refresh();});actions.addView(close,new LinearLayout.LayoutParams(dp(44),dp(44)));row.addView(actions);FrameLayout holder=new FrameLayout(getContext());FrameLayout.LayoutParams rp=new FrameLayout.LayoutParams(-1,-2);rp.bottomMargin=dp(10);holder.addView(row,rp);return holder;
        }
    }
    private ImageButton icon(String name,String label){ImageButton button=new ImageButton(getContext());button.setImageDrawable(new StudioIcon(name));button.setScaleType(ImageView.ScaleType.FIT_CENTER);button.setPadding(dp(12),dp(12),dp(12),dp(12));button.setBackgroundColor(Color.TRANSPARENT);button.setContentDescription(label);return button;}
    private Button button(String label){Button button=new Button(getContext());StudioTypography.button(button);button.setText(label);button.setBackgroundColor(Color.TRANSPARENT);return button;}
    private TextView text(String value,int size){TextView view=new TextView(getContext());view.setText(value);StudioTypography.text(view,size);view.setTextColor(StudioTypography.INK);return view;}
    private GradientDrawable round(int fill,int stroke,int radius){GradientDrawable shape=new GradientDrawable();shape.setColor(fill);shape.setCornerRadius(dp(radius));if(stroke!=0)shape.setStroke(dp(stroke==StudioTypography.INK?2:1),stroke);return shape;}
    private int dp(int value){return StudioTypography.dp(getContext(),value);}
}
